		if(direction == buffer_seek::sk_absolute && offset == size_) {
			return;
		}

		auto tail = root_.prev;

		switch(direction) {
			case buffer_seek::sk_backward:
				size_ -= offset;
				break;
			case buffer_seek::sk_forward:
				size_ += offset;
				break;
			case buffer_seek::sk_absolute:
				size_ = offset;
				offset = abs_seek_offset(offset);
				break;
