using namespace hexi::detail;

template<typename T>
std::size_t encode_varint(hexi::pmc::binary_stream_writer& writer, T value) {
    std::size_t bytes_written = 0;

    // Encode the value using varint encoding
    // Each byte stores 7 bits of data, with the MSB indicating if more bytes follow
    do {
        std::uint8_t byte = static_cast<std::uint8_t>(value & 0x7F); // Get lower 7 bits
        value >>= 7; // Shift right by 7 bits

        if (value != 0) {
            byte |= 0x80; // Set MSB to indicate more bytes follow
        }

        writer.put(byte);
        bytes_written++;
    } while (value != 0);

    return bytes_written;
}

template<typename T>
T decode_varint(hexi::pmc::binary_stream_reader& reader) {
    T result = 0;
    int shift = 0;

    // Decode the varint by reading bytes until we find one without MSB set
    while (true) {
        std::uint8_t byte = reader.get<std::uint8_t>();

        // Extract the lower 7 bits and add to result at the appropriate position
        result |= static_cast<T>(byte & 0x7F) << shift;

        // If MSB is 0, this is the last byte
        if ((byte & 0x80) == 0) {
            break;
        }

        shift += 7;
    }

    return result;
}

template<typename T>
bool encode_decode_roundtrip(T original_value) {
    // Create a buffer for encoding/decoding
    std::vector<std::byte> buffer;
    hexi::pmc::buffer_adaptor<std::vector<std::byte>> adaptor(buffer, init_empty);

    // Encode the value
    hexi::pmc::binary_stream_writer writer(adaptor);
    encode_varint(writer, original_value);

    // Decode the value
    hexi::pmc::binary_stream_reader reader(adaptor);
    T decoded_value = decode_varint<T>(reader);

    // Verify roundtrip correctness
    return original_value == decoded_value;
}
