		if constexpr(memcpy_read<container_type, binary_stream_reader>) {
			container.resize(count);

			const auto bytes = count * sizeof(cvalue_type);
			SAFE_READ(container.data(), bytes, void());
		} else {
			for(count_type i = 0; i < count; ++i) {
